class Solution:
    def maxWidthRamp(self, nums: List[int]) -> int:
        stack = []
        for i, v in enumerate(nums):
            if not stack or nums[stack[-1]] > v:
                stack.append(i)
        res = 0
        for j in range(len(nums)-1, -1, -1):
            while stack and nums[stack[-1]] <= nums[j]:
                res = max(res, j - stack.pop())
        return res

class Solution:
    def minAreaFreeRect(self, points: List[List[int]]) -> float:
        from itertools import combinations
        ps = set(map(tuple, points))
        res = float('inf')
        pts = [tuple(p) for p in points]
        for (x1,y1),(x2,y2),(x3,y3) in combinations(pts, 3):
            if (x2-x1)*(x3-x1)+(y2-y1)*(y3-y1)==0:
                x4,y4=x2+x3-x1,y2+y3-y1
                if (x4,y4) in ps:
                    a=((x2-x1)**2+(y2-y1)**2)**0.5
                    b=((x3-x1)**2+(y3-y1)**2)**0.5
                    res=min(res,a*b)
        return res if res<float('inf') else 0.0

class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dp(i, t):
            if t == 0: return 0
            if t == 1: return i if i > 0 else 2
            if i >= 40: return float('inf')
            r = t % x
            cost_i = i if i > 0 else 2
            return min(r*cost_i + dp(i+1, t//x), (x-r)*cost_i + dp(i+1, t//x+1))
        return dp(0, target) - 1

