class Solution:
    def spellchecker(self, wordlist: List[str], queries: List[str]) -> List[str]:
        words = set(wordlist)
        cap, vowel = {}, {}
        def devowel(w):
            return ''.join('*' if c in 'aeiou' else c for c in w.lower())
        for w in wordlist:
            cap.setdefault(w.lower(), w)
            vowel.setdefault(devowel(w), w)
        res = []
        for q in queries:
            if q in words: res.append(q)
            elif q.lower() in cap: res.append(cap[q.lower()])
            elif devowel(q) in vowel: res.append(vowel[devowel(q)])
            else: res.append('')
        return res

