class Solution:
    def oddEvenJumps(self, arr: List[int]) -> int:
        n = len(arr)
        def make(idxs):
            jump = [None]*n
            stack = []
            for i in idxs:
                while stack and stack[-1] < i:
                    jump[stack.pop()] = i
                stack.append(i)
            return jump
        odd_jump = make(sorted(range(n), key=lambda i: (arr[i], i)))
        even_jump = make(sorted(range(n), key=lambda i: (-arr[i], i)))
        odd, even = [False]*n, [False]*n
        odd[-1] = even[-1] = True
        for i in range(n-2, -1, -1):
            if odd_jump[i] is not None: odd[i] = even[odd_jump[i]]
            if even_jump[i] is not None: even[i] = odd[even_jump[i]]
        return sum(odd)

