class Solution:
    def mergeStones(self, stones: List[int], k: int) -> int:
        n = len(stones)
        if (n-1) % (k-1) != 0: return -1
        prefix = [0]*(n+1)
        for i in range(n): prefix[i+1] = prefix[i]+stones[i]
        dp = [[0]*n for _ in range(n)]
        for l in range(k, n+1):
            for i in range(n-l+1):
                j = i+l-1
                dp[i][j] = float('inf')
                for m in range(i, j, k-1):
                    dp[i][j] = min(dp[i][j], dp[i][m]+dp[m+1][j])
                if (j-i)%(k-1) == 0:
                    dp[i][j] += prefix[j+1]-prefix[i]
        return dp[0][n-1]

class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        from collections import defaultdict
        rows, cols, diag, anti = defaultdict(int), defaultdict(int), defaultdict(int), defaultdict(int)
        lit = set()
        for r, c in lamps:
            if (r,c) not in lit:
                lit.add((r,c))
                rows[r]+=1; cols[c]+=1; diag[r-c]+=1; anti[r+c]+=1
        res = []
        for r, c in queries:
            if rows[r] or cols[c] or diag[r-c] or anti[r+c]:
                res.append(1)
            else:
                res.append(0)
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr, nc = r+dr, c+dc
                    if (nr,nc) in lit:
                        lit.remove((nr,nc))
                        rows[nr]-=1; cols[nc]-=1; diag[nr-nc]-=1; anti[nr+nc]-=1
        return res

