class Solution:
    def clumsy(self, n: int) -> int:
        stack = [n]
        ops = ['*', '//', '+', '-']
        idx = 0
        for i in range(n-1, 0, -1):
            op = ops[idx % 4]
            if op == '*': stack[-1] *= i
            elif op == '//': stack[-1] = int(stack[-1]/i)
            elif op == '+': stack.append(i)
            else: stack.append(-i)
            idx += 1
        return sum(stack)

