class Solution:
    def bstFromPreorder(self, preorder: List[int]) -> Optional[TreeNode]:
        self.i = 0
        def build(bound):
            if self.i == len(preorder) or preorder[self.i] > bound:
                return None
            val = preorder[self.i]
            self.i += 1
            node = TreeNode(val)
            node.left = build(val)
            node.right = build(bound)
            return node
        return build(float('inf'))

