class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo+hi)//2
            d, cur = 1, 0
            for w in weights:
                if cur+w > mid: d += 1; cur = 0
                cur += w
            if d <= days: hi = mid
            else: lo = mid+1
        return lo

class Solution:
    def numDupDigitsAtMostN(self, n: int) -> int:
        digits = list(map(int, str(n+1)))
        k = len(digits)
        cnt = 0
        # count numbers with fewer digits
        for i in range(1, k):
            cnt += 9 * self.perm(9, i-1)
        # count numbers with same digits
        seen = set()
        for i, d in enumerate(digits):
            start = 0 if i else 1
            for j in range(start, d):
                if j not in seen:
                    cnt += self.perm(9-i, k-i-1)
            if d in seen: break
            seen.add(d)
        return n - cnt
    def perm(self, m, n):
        r = 1
        for i in range(n): r *= m-i
        return r

