        m, n = len(grid), len(grid[0])
        def dfs(i, j):
            if i<0 or i>=m or j<0 or j>=n or grid[i][j]!=1: return
            grid[i][j] = 0
            for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(i+di,j+dj)
        for i in range(m):
            for j in range(n):
                if (i==0 or i==m-1 or j==0 or j==n-1) and grid[i][j]==1:
                    dfs(i,j)
        return sum(grid[i][j] for i in range(m) for j in range(n))
